window.EP = {"name": "ch1", "label": "एपिसोड 1", "en": "Room Locked, Lady Dead, Professor Hungry", "duration": 1725.79, "title": [{"start": 5.5, "end": 6.88, "text": "हिडन उत्तराखंड"}, {"start": 7.43, "end": 10.18, "text": "अ बुक बाय, पार्थ डी. जोशी"}, {"start": 10.73, "end": 17.58, "text": "पार्ट वन। गढ़वाल फ़ॉग। … चैप्टर वन। रूम लॉक्ड, लेडी डेड, प्रोफ़ेसर हंग्री"}, {"start": 18.13, "end": 19.84, "text": "डे वन। मसूरी"}], "captions": [{"start": 21.39, "end": 26.82, "text": "इस ट्रिप का पहला झूठ शाओनी का था, और उसने ये झूठ सुबह पाँच-चालीस बजे,", "who": "", "voice": "narrator", "diary": false}, {"start": 26.82, "end": 31.79, "text": "अहमदाबाद एयरपोर्ट पर, डिपार्चर बोर्ड के नीचे खड़े होकर बोला था।", "who": "", "voice": "narrator", "diary": false}, {"start": 31.79, "end": 36.75, "text": "हाथ में इतनी मोटी प्रिंटेड आइटिनरेरी, कि उससे गोली रोकी जा सके।", "who": "", "voice": "narrator", "diary": false}, {"start": 37.2, "end": 38.53, "text": "बस रिलैक्स करेंगे।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 38.73, "end": 39.38, "text": "उसने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 39.38, "end": 43.61, "text": "बोला उसने मुझसे, लेकिन देख वो अपने भाई को रही थी, वैसे ही,", "who": "", "voice": "narrator", "diary": false}, {"start": 43.61, "end": 47.91, "text": "जैसे आप उस डॉग को देखते हैं जिसने अभी-अभी गिलहरी देख ली हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 48.11, "end": 49.48, "text": "नो एडवेंचर।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 49.48, "end": 50.73, "text": "नो ड्रामा।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 50.73, "end": 53.35, "text": "माउंटेन्स, चाय, नींद।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 53.8, "end": 55.74, "text": "क्षितिज ने ऊपर नहीं देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 55.74, "end": 59.7, "text": "वो अपने सूटकेस पर बैठा था, घुटने पर डायरी खुली हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 59.7, "end": 62.03, "text": "वही मोटी, रबर-बैंड वाली डायरी,", "who": "", "voice": "narrator", "diary": false}, {"start": 62.03, "end": 66.0, "text": "जो वो बारह साल की उम्र से हर जगह साथ लेकर घूमता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 66.0, "end": 67.86, "text": "और वो अभी से लिख रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 68.31, "end": 69.18, "text": "डे ज़ीरो।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 69.38, "end": 72.34, "text": "उसने कोर्ट रिपोर्टर जैसी फ़्लैट आवाज़ में पढ़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 72.54, "end": 74.33, "text": "फ़ाइव-फ़ोर्टी ए-एम।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 74.33, "end": 76.69, "text": "दीदी कहती हैं, नो ड्रामा।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 76.89, "end": 80.23, "text": "उसने किसी चीज़ के नीचे दो बार लाइन खींची।", "who": "", "voice": "narrator", "diary": false}, {"start": 80.43, "end": 80.88, "text": "नोटेड।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 80.88, "end": 82.59, "text": "फ़्यूचर एविडेंस के लिए।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 83.04, "end": 83.73, "text": "क्षितिज।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 83.93, "end": 87.03, "text": "शाओनी ने आइटिनरेरी से उसके सिर पर हल्का सा मारा।", "who": "", "voice": "narrator", "diary": false}, {"start": 87.23, "end": 88.23, "text": "पेज वन।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 88.23, "end": 88.95, "text": "पढ़ो।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 89.4, "end": 90.03, "text": "उसने पढ़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 90.03, "end": 91.28, "text": "फिर मेरी तरफ़ मुड़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 91.48, "end": 94.47, "text": "भाई, पेज वन पे एक कॉलम है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 94.47, "end": 95.16, "text": "रिस्क।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 95.16, "end": 97.68, "text": "हर रो में लिखा है, लो।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 98.13, "end": 99.3, "text": "क्योंकि रिस्क लो है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 99.5, "end": 100.36, "text": "शाओनी ने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 100.81, "end": 101.69, "text": "हर रो में।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 101.89, "end": 104.43, "text": "क्षितिज ने दोहराया, मुझसे, उससे नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 104.63, "end": 105.8, "text": "फ़ोर्टी-सेवन रोज़।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 105.8, "end": 108.21, "text": "किसी भी चीज़ का रिस्क मीडियम नहीं है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 108.21, "end": 109.52, "text": "केदारनाथ का भी नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 109.97, "end": 113.56, "text": "पहाड़ इन दोनों को अपनी पकड़ में लें,", "who": "", "voice": "narrator", "diary": false}, {"start": 113.56, "end": 119.35, "text": "उससे पहले मैं चाहता हूँ कि आप समझ लें कि ये दोनों हैं कौन।", "who": "", "voice": "narrator", "diary": false}, {"start": 119.35, "end": 121.44, "text": "तो, सबसे छोटा वर्ज़न।", "who": "", "voice": "narrator", "diary": false}, {"start": 121.89, "end": 127.16, "text": "शाओनी इतने सालों से मेरी दोस्त है कि हमने एक-दूसरे के साथ पोलाइट होना छोड़ दिया है,", "who": "", "voice": "narrator", "diary": false}, {"start": 127.16, "end": 129.75, "text": "जो इंडिया में प्यार का सबसे ऊँचा लेवल है।", "who": "", "voice": "narrator", "diary": false}, {"start": 129.75, "end": 131.59, "text": "मैं जितने लोगों को जानता हूँ,", "who": "", "voice": "narrator", "diary": false}, {"start": 131.59, "end": 134.76, "text": "उनमें वो अकेली है जो टर्म्स एंड कंडीशन्स पढ़ती है,", "who": "", "voice": "narrator", "diary": false}, {"start": 134.76, "end": 136.28, "text": "और फिर उनसे बहस करती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 136.28, "end": 140.22, "text": "जब कोई चीज़ उसे डराती है, तो वो उसकी नंबर्ड लिस्ट बना देती है,", "who": "", "voice": "narrator", "diary": false}, {"start": 140.22, "end": 144.34, "text": "और पॉइंट फ़ोर तक पहुँचते-पहुँचते वो डर बस एक प्रॉब्लम रह जाता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 144.34, "end": 146.62, "text": "और प्रॉब्लम्स, वो फ़िक्स कर सकती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 146.62, "end": 147.95, "text": "वो इसे लॉजिक कहती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 147.95, "end": 149.79, "text": "बाक़ी सब इसे हिम्मत कहते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 149.79, "end": 151.75, "text": "वो मर जाएगी, पर ये मानेगी नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 152.2, "end": 154.18, "text": "क्षितिज, उसका छोटा भाई,", "who": "", "voice": "narrator", "diary": false}, {"start": 154.18, "end": 157.97, "text": "सबसे शांत इंसान है जिसने कभी मुझे हँसाया हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 157.97, "end": 159.78, "text": "वो जोक्स नहीं सुनाता।", "who": "", "voice": "narrator", "diary": false}, {"start": 159.78, "end": 161.67, "text": "वो चीज़ें लिख लेता है,", "who": "", "voice": "narrator", "diary": false}, {"start": 161.67, "end": 166.49, "text": "और फिर उन्हें बिल्कुल ग़लत मोमेंट पर पढ़कर सुना देता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 166.94, "end": 167.43, "text": "और मैं?", "who": "", "voice": "narrator", "diary": false}, {"start": 167.43, "end": 170.92, "text": "मैं एक प्रोफ़ेसर हूँ, एक डेवलपर, और एक स्टोरीटेलर।", "who": "", "voice": "narrator", "diary": false}, {"start": 170.92, "end": 175.32, "text": "लंच से पहले लगभग इसी ऑर्डर में, और डिनर के बाद उल्टे ऑर्डर में।", "who": "", "voice": "narrator", "diary": false}, {"start": 175.32, "end": 177.13, "text": "मैं हर शाम दीया जलाता हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 177.13, "end": 180.13, "text": "हर मंदिर के सामने से हाथ जोड़कर निकलता हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 180.13, "end": 183.28, "text": "और जब मैं नर्वस होता हूँ, तो जोक्स मारता हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 183.28, "end": 185.93, "text": "जितना ज़्यादा नर्वस, उतने अच्छे जोक्स।", "who": "", "voice": "narrator", "diary": false}, {"start": 185.93, "end": 187.18, "text": "इस पर नज़र रखिएगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 187.18, "end": 191.16, "text": "इस ट्रिप पर, यही एक इंस्ट्रूमेंट था जो कभी फ़ेल नहीं हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 191.61, "end": 192.73, "text": "और भूत?", "who": "", "voice": "narrator", "diary": false}, {"start": 192.93, "end": 196.27, "text": "मैंने शाओनी से पूछा, क्योंकि किसी को तो पूछना था।", "who": "", "voice": "narrator", "diary": false}, {"start": 196.72, "end": 200.64, "text": "उसने मुझे वो लुक दिया, जो वो किसी छेद वाली थ्योरी को देती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 200.84, "end": 201.33, "text": "पार्थ।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 201.33, "end": 203.28, "text": "भूत का कोई डेटा नहीं है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 203.28, "end": 204.67, "text": "तुम प्रोफ़ेसर हो।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 204.67, "end": 205.15, "text": "बिहेव।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 205.6, "end": 209.6, "text": "मैं चाहूँगा कि रिकॉर्ड में रहे… कि मैंने कोशिश की थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 211.1, "end": 215.9, "text": "देहरादून एयरपोर्ट पर, ग्रे जैकेट और काली गढ़वाली टोपी पहने एक आदमी,", "who": "", "voice": "narrator", "diary": false}, {"start": 215.9, "end": 219.34, "text": "हाथ बाँधे एक सफ़ेद एस-यू-वी से टेक लगाए खड़ा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 219.34, "end": 223.42, "text": "वो अराइवल गेट को ऐसे देख रहा था, जैसे कोई कस्टम्स ऑफ़िसर,", "who": "", "voice": "narrator", "diary": false}, {"start": 223.42, "end": 226.0, "text": "जिसने हर तरह के टूरिस्ट देख लिए हों,", "who": "", "voice": "narrator", "diary": false}, {"start": 226.0, "end": 228.0, "text": "और किसी को भी पास न किया हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 228.0, "end": 231.44, "text": "पीछे के शीशे पर, गुलाबी स्टिकर वाले अक्षरों में,", "who": "", "voice": "narrator", "diary": false}, {"start": 231.44, "end": 233.52, "text": "किसी ने एक शब्द चिपका रखा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 234.22, "end": 234.83, "text": "बसंती।", "who": "", "voice": "narrator", "diary": false}, {"start": 235.53, "end": 239.19, "text": "मैं अपनी बेस्ट प्रोफ़ेसर वाली स्माइल लेकर उसके पास गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 239.39, "end": 240.04, "text": "टैक्सी?", "who": "", "voice": "narrator", "diary": false}, {"start": 240.04, "end": 240.59, "text": "मसूरी?", "who": "", "voice": "narrator", "diary": false}, {"start": 241.04, "end": 241.67, "text": "मसूरी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 241.87, "end": 242.94, "text": "उसने हामी भरी।", "who": "", "voice": "narrator", "diary": false}, {"start": 242.94, "end": 246.53, "text": "उसकी नज़र हम तीनों पर घूमी: शाओनी की आइटिनरेरी,", "who": "", "voice": "narrator", "diary": false}, {"start": 246.53, "end": 249.14, "text": "क्षितिज की डायरी, मेरे तीन स्वेटर।", "who": "", "voice": "narrator", "diary": false}, {"start": 249.34, "end": 249.71, "text": "फिर?", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 250.16, "end": 252.22, "text": "फिर पूरा उत्तराखंड।", "who": "", "voice": "narrator", "diary": false}, {"start": 252.22, "end": 253.42, "text": "तीन हफ़्ते।", "who": "", "voice": "narrator", "diary": false}, {"start": 253.42, "end": 255.92, "text": "मंदिर, पहाड़, कहानियाँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 256.12, "end": 256.91, "text": "मैं रुका।", "who": "", "voice": "narrator", "diary": false}, {"start": 257.11, "end": 257.99, "text": "आप फ़्री हो?", "who": "", "voice": "narrator", "diary": false}, {"start": 258.44, "end": 259.64, "text": "उसने मुझे एक लंबे,", "who": "", "voice": "narrator", "diary": false}, {"start": 259.64, "end": 263.67, "text": "अजीब से मोमेंट तक देखा… जैसे तय कर रहा हो कि मैं कस्टमर हूँ,", "who": "", "voice": "narrator", "diary": false}, {"start": 263.67, "end": 264.47, "text": "या प्रॉब्लम।", "who": "", "voice": "narrator", "diary": false}, {"start": 264.47, "end": 267.29, "text": "फिर उसने गाड़ी के बोनट को धीरे से थपथपाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 267.29, "end": 269.64, "text": "जैसे कोई बूढ़े घोड़े को थपथपाता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 270.09, "end": 272.86, "text": "बसंती ने इससे बुरे लोग देखे हैं।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 273.06, "end": 273.65, "text": "उसने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 273.65, "end": 276.33, "text": "फिर डिनर प्लेट जितना बड़ा हाथ आगे बढ़ाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 276.53, "end": 277.99, "text": "गब्बर सिंह नेगी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 277.99, "end": 279.17, "text": "फ़िक्स्ड रेट।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 279.17, "end": 281.09, "text": "… भूतों का एक्स्ट्रा।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 281.54, "end": 282.63, "text": "मैंने हाथ मिलाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 282.63, "end": 285.07, "text": "मैंने बसंती नाम की गाड़ी चलाने के लिए,", "who": "", "voice": "narrator", "diary": false}, {"start": 285.07, "end": 287.06, "text": "गब्बर नाम के आदमी को हायर किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 287.06, "end": 288.03, "text": "जान-बूझकर किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 288.03, "end": 289.7, "text": "और मुझे… कोई रिग्रेट नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 290.15, "end": 290.94, "text": "गब्बर सिंह?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 291.14, "end": 293.84, "text": "क्षितिज ने पूछा, पेन पहले से चल रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 294.04, "end": 294.76, "text": "असली नाम?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 295.21, "end": 295.93, "text": "असली नाम!", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 296.13, "end": 297.84, "text": "गब्बर ने डिक्की खोली,", "who": "", "voice": "narrator", "diary": false}, {"start": 297.84, "end": 303.25, "text": "और शाओनी का सूटकेस अंदर ऐसे फेंका जैसे उसने उसकी बेइज़्ज़ती की हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 303.45, "end": 306.38, "text": "मेरे पापा बस कंडक्टर थे, हल्द्वानी में।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 306.38, "end": 309.02, "text": "एक सर्दी में शोले… उन्नीस बार देखी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 309.02, "end": 311.13, "text": "अगले बसंत में, मैं पैदा हुआ।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 311.33, "end": 313.01, "text": "उसने डिक्की धड़ाम से बंद की।", "who": "", "voice": "narrator", "diary": false}, {"start": 313.21, "end": 315.69, "text": "हीरो का नाम तो सब रखते हैं, उन्होंने कहा।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 316.14, "end": 316.84, "text": "और बसंती?", "who": "", "voice": "narrator", "diary": false}, {"start": 317.04, "end": 317.92, "text": "मैंने पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 318.37, "end": 322.27, "text": "पचास साल से, हर पुलिसवाला मुझसे पूछता है… कितने आदमी थे।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 322.47, "end": 324.46, "text": "उसने ड्राइवर वाला दरवाज़ा खोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 324.66, "end": 327.24, "text": "तो जब अपनी गाड़ी ली, नाम रख दिया बसंती।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 327.24, "end": 330.42, "text": "अब कोई पूछता है, तो मैं कहता हूँ… बसंती से पूछो!", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 330.87, "end": 335.53, "text": "शाओनी हँस पड़ी, जो वो अजनबियों के सामने लगभग कभी नहीं करती।", "who": "", "voice": "narrator", "diary": false}, {"start": 335.53, "end": 340.82, "text": "मुझे लगता है, वही मोमेंट था जब गब्बर ने तय किया कि हम कस्टमर्स हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 340.82, "end": 341.93, "text": "प्रॉब्लम नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 343.43, "end": 345.61, "text": "मसूरी की सड़क ऐसे चढ़ती है,", "who": "", "voice": "narrator", "diary": false}, {"start": 345.61, "end": 348.85, "text": "जैसे उसे कहीं पहुँचने में देर हो रही हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 348.85, "end": 353.37, "text": "चौदहवें हेयरपिन के आस-पास, क्षितिज ने बोलना बंद कर दिया,", "who": "", "voice": "narrator", "diary": false}, {"start": 353.37, "end": 356.77, "text": "और तभी आपको पता चलता है कि सड़क सीरियस है।", "who": "", "voice": "narrator", "diary": false}, {"start": 356.77, "end": 360.25, "text": "बीसवें के आस-पास, गब्बर ने बोलना शुरू किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 360.7, "end": 365.23, "text": "उसने मेरे आगे से हाथ बढ़ाकर ग्लवबॉक्स खोला, और मोड़ से नज़र हटाए बिना,", "who": "", "voice": "narrator", "diary": false}, {"start": 365.23, "end": 367.88, "text": "एक लैमिनेटेड कार्ड मेरी गोद में डाल दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 368.33, "end": 369.69, "text": "मसूरी, फ़िक्स्ड।", "who": "", "voice": "narrator", "diary": false}, {"start": 369.69, "end": 371.22, "text": "चार धाम, फ़िक्स्ड।", "who": "", "voice": "narrator", "diary": false}, {"start": 371.22, "end": 374.02, "text": "भूत की कहानी, सौ रुपये एक्स्ट्रा।", "who": "", "voice": "narrator", "diary": false}, {"start": 374.02, "end": 376.48, "text": "असली भूत की कहानी… नेगोशिएबल।", "who": "", "voice": "narrator", "diary": false}, {"start": 376.93, "end": 378.71, "text": "असली और नक़ली में फ़र्क़ क्या है?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 378.91, "end": 380.83, "text": "क्षितिज ने पीछे की सीट से पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 381.28, "end": 385.0, "text": "गब्बर की आँखों ने रियर-व्यू मिरर में उसे ढूँढा।", "who": "", "voice": "narrator", "diary": false}, {"start": 385.0, "end": 388.32, "text": "एक सेकंड के लिए, वो शोमैन कहीं और चला गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 388.77, "end": 390.44, "text": "नक़ली कहानी मैं सुनाता हूँ।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 390.64, "end": 391.28, "text": "उसने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 391.48, "end": 393.23, "text": "असली कहानी… मेरी नानी सुनाती थी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 393.43, "end": 395.03, "text": "उसने फिर सड़क की तरफ़ देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 395.23, "end": 397.15, "text": "वो मैं किसी को नहीं सुनाता।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 397.6, "end": 402.01, "text": "फिर वो मुस्कुराया, एक गाय को हॉर्न दिया, और मेरी तरफ़ मुड़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 402.21, "end": 403.23, "text": "प्रोफ़ेसर साहब।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 403.23, "end": 404.79, "text": "सवॉय में रुक रहे हो ना?", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 404.79, "end": 406.96, "text": "वहाँ एक अंग्रेज़ मेमसाहब मरी थी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 406.96, "end": 408.39, "text": "उन्नीस सौ ग्यारह में।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 408.39, "end": 409.95, "text": "दरवाज़ा अंदर से बंद था।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 409.95, "end": 411.78, "text": "आज तक कोई नहीं जानता, कैसे।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 411.98, "end": 413.49, "text": "उसने एक उँगली उठाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 413.69, "end": 414.33, "text": "सौ रुपये।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 414.33, "end": 415.59, "text": "फ़ैमिली डिस्काउंट।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 416.04, "end": 417.47, "text": "इसीलिए तो बुक किया है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 417.67, "end": 420.14, "text": "शाओनी ने पीछे से कहा, फ़ोन से नज़र उठाए बिना।", "who": "", "voice": "narrator", "diary": false}, {"start": 420.34, "end": 421.12, "text": "हिस्टॉरिक है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 421.57, "end": 421.97, "text": "दीदी।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 422.17, "end": 423.04, "text": "क्षितिज ने कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 423.24, "end": 427.39, "text": "हिस्टॉरिक और हॉन्टेड, हिंदी में एक ही शब्द है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 427.84, "end": 430.22, "text": "क्षितिज की हिंदी मुझसे बेहतर नहीं है,", "who": "", "voice": "narrator", "diary": false}, {"start": 430.22, "end": 433.57, "text": "फिर भी उस गाड़ी में कोई उसे ग़लत साबित नहीं कर पाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 435.07, "end": 441.95, "text": "सवॉय, माल रोड से थोड़ा हटकर ऐसे बैठा है, जैसे किसी शादी में कोई पुरानी आंटी: ग्रैंड,", "who": "", "voice": "narrator", "diary": false}, {"start": 441.95, "end": 446.3, "text": "गॉथिक, और अपने बाद आने वाले हर इंसान से थोड़ी नाराज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 446.3, "end": 448.59, "text": "ये उन्नीस सौ दो में खुला था।", "who": "", "voice": "narrator", "diary": false}, {"start": 448.59, "end": 450.39, "text": "यहाँ वायसरॉय नाचे हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 450.39, "end": 452.11, "text": "पोएट्स ने यहाँ पी है।", "who": "", "voice": "narrator", "diary": false}, {"start": 452.11, "end": 456.78, "text": "और लॉबी को देखकर लग रहा था कि आज, रिंग लाइट वाला एक आदमी,", "who": "", "voice": "narrator", "diary": false}, {"start": 456.78, "end": 459.73, "text": "यहाँ अपनी बेइज़्ज़ती करवाने वाला है।", "who": "", "voice": "narrator", "diary": false}, {"start": 460.18, "end": 462.53, "text": "घोस्ट फ़ैमिली, क्या हाल है!", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 462.73, "end": 464.65, "text": "वो जिम्बल पर लगे फ़ोन में चिल्लाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 464.85, "end": 468.0, "text": "मैं हूँ घोस्टबस्टर गोलू, और आज हम लाइव हैं,", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 468.0, "end": 470.26, "text": "इंडिया के सबसे हॉन्टेड होटल से!", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 470.71, "end": 476.04, "text": "टमाटर सूप की ट्रे लिए एक वेटर, सीधा उसके शॉट के बीच से निकल गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 476.04, "end": 476.95, "text": "गोलू चीख़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 476.95, "end": 477.87, "text": "सूप बच गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 477.87, "end": 479.95, "text": "गोलू की इज़्ज़त नहीं बची।", "who": "", "voice": "narrator", "diary": false}, {"start": 480.4, "end": 483.02, "text": "मैं उसे ध्यान से डिस्क्राइब करूँगा,", "who": "", "voice": "narrator", "diary": false}, {"start": 483.02, "end": 486.85, "text": "क्योंकि मैं चाहता हूँ कि आप उसे बिल्कुल वैसे देखें,", "who": "", "voice": "narrator", "diary": false}, {"start": 486.85, "end": 489.1, "text": "जैसे मैंने उसे उस शाम देखा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 489.1, "end": 492.32, "text": "और मैं चाहता हूँ कि आप ये बाद में याद रखें।", "who": "", "voice": "narrator", "diary": false}, {"start": 492.77, "end": 494.63, "text": "उम्र, कोई चौबीस-पच्चीस।", "who": "", "voice": "narrator", "diary": false}, {"start": 494.63, "end": 499.49, "text": "चमकती लाल पफ़र जैकेट, जिस पर अभी तक पैकेट की तह के निशान थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 499.49, "end": 505.15, "text": "ब्रैंड-न्यू जिम्बल, ब्रैंड-न्यू रिंग लाइट, ब्रैंड-न्यू सफ़ेद स्नीकर्स,", "who": "", "voice": "narrator", "diary": false}, {"start": 505.15, "end": 508.39, "text": "जिनकी कभी कीचड़ से मुलाक़ात नहीं हुई थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 508.39, "end": 513.16, "text": "उसकी हर चीज़ नई थी, लाउड थी, और पिछले हफ़्ते ख़रीदी हुई थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 513.61, "end": 515.95, "text": "हर चीज़… सिवाय उसकी टोपी के।", "who": "", "voice": "narrator", "diary": false}, {"start": 515.95, "end": 522.54, "text": "वो एक फीकी पड़ चुकी नीली ऊनी टोपी थी, किनारों से ऊन पतली और रोएँदार हो चुकी थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 522.54, "end": 525.46, "text": "और सामने एक छोटा सा कढ़ाई वाला बैज,", "who": "", "voice": "narrator", "diary": false}, {"start": 525.46, "end": 528.04, "text": "इतना घिसा हुआ कि पढ़ा न जा सके।", "who": "", "voice": "narrator", "diary": false}, {"start": 528.04, "end": 532.72, "text": "ऐसा लगता था, जैसे वो टोपी किसी चीज़ की चोटी तक हो आई हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 533.17, "end": 534.39, "text": "मैंने उसे नोटिस किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 534.39, "end": 537.09, "text": "और उसे यूट्यूबर फ़ैशन वाली फ़ाइल में डाल दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 537.09, "end": 540.36, "text": "नोटिस करने के साथ यही प्रॉब्लम है… वो सिर्फ़ आधा काम है।", "who": "", "voice": "narrator", "diary": false}, {"start": 540.81, "end": 545.37, "text": "दस मिनट बाद, उसने अपना लाइव स्ट्रीम वैसे ही ख़त्म किया, जैसे,", "who": "", "voice": "narrator", "diary": false}, {"start": 545.37, "end": 549.62, "text": "मुझे बाद में पता चला, वो अपनी हर एक वीडियो ख़त्म करता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 549.62, "end": 551.93, "text": "लेंस की तरफ़ झुका, और आँख मारी।", "who": "", "voice": "narrator", "diary": false}, {"start": 552.38, "end": 557.04, "text": "और याद रखना, घोस्ट फ़ैमिली: पहाड़ पे अकेले मत जाना!", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 557.49, "end": 559.84, "text": "उसके फ़ोन की लाल लाइट बुझ गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 559.84, "end": 561.78, "text": "उसने जिम्बल फ़ोल्ड किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 561.78, "end": 565.18, "text": "और मैंने देखा कि उसके होंठ एक बार और हिले,", "who": "", "voice": "narrator", "diary": false}, {"start": 565.18, "end": 568.09, "text": "चुपचाप, वही पाँच शब्द, किसी से नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 569.59, "end": 570.76, "text": "मेरा फ़ोन बजा।", "who": "", "voice": "narrator", "diary": false}, {"start": 570.76, "end": 571.26, "text": "मम्मी।", "who": "", "voice": "narrator", "diary": false}, {"start": 571.96, "end": 575.77, "text": "मैं बाक़ियों से हटकर खिड़की के पास गया, और फ़ोन उठाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 575.77, "end": 580.72, "text": "पीछे, शाओनी रिसेप्शनिस्ट को धीरे-धीरे, नंबर्ड पॉइंट्स में समझा रही थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 580.72, "end": 583.2, "text": "कि बुकिंग में दो रूम क्यों लिखा है,", "who": "", "voice": "narrator", "diary": false}, {"start": 583.2, "end": 587.02, "text": "जबकि उसने साफ़-साफ़ दो रूम और एक रीडिंग लैंप माँगा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 587.47, "end": 587.99, "text": "पहुँच गए?", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 588.19, "end": 588.98, "text": "मम्मी ने पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 589.43, "end": 590.75, "text": "पहुँच गए, मम्मी।", "who": "", "voice": "narrator", "diary": false}, {"start": 591.2, "end": 592.0, "text": "स्वेटर पहना?", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 592.45, "end": 593.07, "text": "तीन।", "who": "", "voice": "narrator", "diary": false}, {"start": 593.52, "end": 594.0, "text": "गुड।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 594.2, "end": 594.77, "text": "एक पॉज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 594.77, "end": 599.23, "text": "अहमदाबाद में, प्रेशर कुकर की सीटी मुझे यहाँ तक सुनाई दे रही थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 599.43, "end": 600.32, "text": "और पार्थ।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 600.32, "end": 602.78, "text": "भूत-वूत के पीछे मत पड़ना।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 603.23, "end": 604.34, "text": "लॉबी के उस पार,", "who": "", "voice": "narrator", "diary": false}, {"start": 604.34, "end": 608.19, "text": "गोलू बड़े इमोशन के साथ एक पर्दे को फ़िल्म कर रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 608.64, "end": 609.02, "text": "मम्मी।", "who": "", "voice": "narrator", "diary": false}, {"start": 609.22, "end": 610.0, "text": "मैंने कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 610.2, "end": 612.12, "text": "मैं भूत के पीछे नहीं पड़ूँगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 612.12, "end": 612.65, "text": "प्रॉमिस।", "who": "", "voice": "narrator", "diary": false}, {"start": 613.1, "end": 615.66, "text": "वो इस ट्रिप का दूसरा झूठ था… मेरा।", "who": "", "voice": "narrator", "diary": false}, {"start": 617.16, "end": 619.67, "text": "डिनर पर मैंने अपनी नोटबुक खोली।", "who": "", "voice": "narrator", "diary": false}, {"start": 619.67, "end": 625.72, "text": "ब्राउन लेदर, थोड़ी घिसी हुई, मेरे फ़ाइनल-ईयर स्टूडेंट्स का फ़ेयरवेल गिफ़्ट,", "who": "", "voice": "narrator", "diary": false}, {"start": 625.72, "end": 629.03, "text": "जिसके कवर के अंदर छपा था: सर, लिखते रहना।", "who": "", "voice": "narrator", "diary": false}, {"start": 629.03, "end": 635.8, "text": "मैं सवॉय वाला केस ठीक से लिखना चाहता था, क्योंकि इस बिल्डिंग में एक असली औरत मरी थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 635.8, "end": 639.11, "text": "और वो रिंग लाइट से बेहतर डिज़र्व करती थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 639.11, "end": 642.83, "text": "एक भी शब्द लिखने से पहले, मैंने आँखें बंद कीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 642.83, "end": 645.73, "text": "और उनके लिए एक छोटी सी प्रार्थना की।", "who": "", "voice": "narrator", "diary": false}, {"start": 645.73, "end": 649.2, "text": "कुछ आदतें मम्मी से आती हैं, कुछ पहाड़ों से,", "who": "", "voice": "narrator", "diary": false}, {"start": 649.2, "end": 653.24, "text": "और मैं आज तक नहीं बता पाया कि कौन सी, किससे आई है।", "who": "", "voice": "narrator", "diary": false}, {"start": 653.69, "end": 656.14, "text": "तो फ़ैक्ट्स ये हैं, जितना कोई जानता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 656.59, "end": 664.39, "text": "उन्नीस सौ ग्यारह में, मिस फ़्रांसेस गार्नेट-ऑर्म, उम्र उनचास, एक स्पिरिचुअलिस्ट, सवॉय में ठहरी थीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 664.39, "end": 667.39, "text": "अपनी साथी मिस ईवा माउंटस्टीफ़न के साथ,", "who": "", "voice": "narrator", "diary": false}, {"start": 667.39, "end": 671.33, "text": "जो सेआंस और क्रिस्टल-गेज़िंग के लिए जानी जाती थीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 671.33, "end": 675.97, "text": "उन्नीस सितंबर की सुबह, जब मिस माउंटस्टीफ़न लखनऊ गई हुई थीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 675.97, "end": 679.6, "text": "मिस गार्नेट-ऑर्म अपने बिस्तर पर मरी हुई मिलीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 679.6, "end": 681.88, "text": "उनका दरवाज़ा… अंदर से लॉक था।", "who": "", "voice": "narrator", "diary": false}, {"start": 681.88, "end": 685.27, "text": "पोस्टमॉर्टम में प्रूसिक एसिड मिला: साइनाइड।", "who": "", "voice": "narrator", "diary": false}, {"start": 685.27, "end": 689.37, "text": "मिस माउंटस्टीफ़न पर मर्डर का केस चला, वो बरी हो गईं,", "who": "", "voice": "narrator", "diary": false}, {"start": 689.37, "end": 692.75, "text": "और जज ने कहा कि सच शायद कभी पता नहीं चलेगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 692.75, "end": 694.8, "text": "लोग कहते हैं, कुछ साल बाद,", "who": "", "voice": "narrator", "diary": false}, {"start": 694.8, "end": 702.68, "text": "अगाथा क्रिस्टी नाम की एक जवान नर्स ने अपना पहला नॉवेल लिखा… एक बंद दरवाज़े के पीछे ज़हर के बारे में।", "who": "", "voice": "narrator", "diary": false}, {"start": 703.13, "end": 705.61, "text": "मैंने ये पूरी टेबल को पढ़कर सुनाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 706.06, "end": 707.82, "text": "सबसे पहले क्षितिज बोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 708.02, "end": 708.72, "text": "तो किसने किया?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 709.17, "end": 710.95, "text": "कोर्ट ने कहा, उन्होंने नहीं किया।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 711.15, "end": 712.58, "text": "शाओनी ने उसे बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 712.58, "end": 716.66, "text": "वो अपनी रोटी को एकदम बराबर चार हिस्सों में काट रही थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 716.86, "end": 717.71, "text": "लॉक्ड रूम।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 717.71, "end": 718.31, "text": "पॉइज़न।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 718.31, "end": 719.76, "text": "साथी शहर से बाहर।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 719.76, "end": 725.05, "text": "तीन ऑप्शन्स: किसी के पास दूसरी चाबी थी, या उन्होंने ख़ुद लिया,", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 725.05, "end": 728.55, "text": "या पुलिस आने से पहले सबूत साफ़ कर दिए गए।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 728.75, "end": 730.11, "text": "उसने एक हिस्सा खाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 730.31, "end": 731.38, "text": "तीन ऑप्शन्स।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 731.38, "end": 732.54, "text": "ज़ीरो प्रूफ़।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 732.99, "end": 733.86, "text": "भूत ने किया।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 734.06, "end": 737.99, "text": "गब्बर ने कहा, जिसने डेज़र्ट के लिए कुर्सी खींच ली थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 737.99, "end": 741.03, "text": "और जिसके इस बारे में बहुत पक्के विचार थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 741.48, "end": 742.37, "text": "या फिर।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 742.57, "end": 743.92, "text": "मेरे पीछे से एक आवाज़ आई,", "who": "", "voice": "narrator", "diary": false}, {"start": 744.12, "end": 749.7, "text": "कोई ऐसा, जो समझता था कि किसी सीक्रेट को छुपाने की सबसे अच्छी जगह,", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 749.7, "end": 754.6, "text": "वो कहानी होती है, जिसे सब पहले से जानने का दावा करते हैं।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 755.3, "end": 755.94, "text": "मैं मुड़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 756.64, "end": 760.14, "text": "वो लगभग चालीस का था, नेवी ब्लू क्वार्टर-ज़िप में,", "who": "", "voice": "narrator", "diary": false}, {"start": 760.14, "end": 763.0, "text": "जो शायद मेरी महीने की सैलरी से महँगी थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 763.0, "end": 767.36, "text": "ऐसा चेहरा, जिस पर आप म्यूचुअल फ़ंड बेचने के लिए भरोसा कर लें।", "who": "", "voice": "narrator", "diary": false}, {"start": 767.36, "end": 770.94, "text": "उसने मुझे ऐसे स्माइल दी, जैसे हम पुराने दोस्त हों,", "who": "", "voice": "narrator", "diary": false}, {"start": 770.94, "end": 772.87, "text": "जिनका कॉन्टैक्ट टूट गया हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 773.32, "end": 773.96, "text": "सॉरी।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 774.16, "end": 774.8, "text": "उसने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 775.0, "end": 776.54, "text": "पेशे की बीमारी है।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 776.54, "end": 777.4, "text": "रोहन सहगल।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 777.4, "end": 780.65, "text": "मैं ट्रेक्स चलाता हूँ: समिट सीक्रेट्स।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 780.65, "end": 782.96, "text": "आपने हमारे ऐड्स देखे होंगे।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 783.41, "end": 784.56, "text": "शाओनी ने देखे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 784.56, "end": 788.59, "text": "उसने लगभग एक बुक कर ही लिया था, जब तक उसने प्राइस नहीं देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 789.04, "end": 793.61, "text": "उसके पीछे, अगली टेबल पर, काली जैकेट में एक बहुत बड़ा आदमी बैठा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 793.61, "end": 797.21, "text": "बड़े ध्यान से, और बिना किसी ख़ुशी के, सूप पी रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 797.21, "end": 799.43, "text": "उसने अपना इंट्रोडक्शन नहीं दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 799.43, "end": 801.85, "text": "किसी ने उसका इंट्रोडक्शन नहीं दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 801.85, "end": 803.37, "text": "वो उस टाइप का आदमी था,", "who": "", "voice": "narrator", "diary": false}, {"start": 803.37, "end": 808.08, "text": "जिसे इंट्रोडक्शन की ज़रूरत नहीं होती… जैसे किसी अलमारी को नहीं होती।", "who": "", "voice": "narrator", "diary": false}, {"start": 808.53, "end": 813.01, "text": "रोहन ने बिना पूछे एक कुर्सी खींच ली, जो अमीर लोग कर सकते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 813.01, "end": 817.35, "text": "और अगले बीस मिनट तक, वो मेरी लाइफ़ का बेस्ट डिनर-कंपनी रहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 817.35, "end": 820.58, "text": "उसे मसूरी के हर होटल के खुलने का साल याद था।", "who": "", "voice": "narrator", "diary": false}, {"start": 820.58, "end": 824.99, "text": "उसे पता था कि कौन से गढ़वाली गाने प्रेमियों के बारे में हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 824.99, "end": 827.57, "text": "और कौन से लैंडस्लाइड्स के बारे में।", "who": "", "voice": "narrator", "diary": false}, {"start": 827.57, "end": 832.42, "text": "उसने गब्बर को, फ़र्राटेदार कुमाऊँनी में, चरवाहों का एक शब्द बताया,", "who": "", "voice": "narrator", "diary": false}, {"start": 832.42, "end": 836.68, "text": "उस बर्फ़ के लिए, जो गिरना बंद कर चुकी हो, पर अभी जमी न हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 836.68, "end": 841.31, "text": "और गब्बर ने, जो आसानी से इम्प्रेस नहीं होता, भौंहें ऊपर कर लीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 841.76, "end": 843.72, "text": "उन बीस मिनटों में कुछ ऐसा हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 843.72, "end": 846.66, "text": "जो मैंने नोटिस नहीं किया, और क्षितिज ने किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 846.66, "end": 850.26, "text": "तो मैं वैसे ही सुनाऊँगा, जैसे उसने मुझे बाद में सुनाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 850.71, "end": 859.81, "text": "सवॉय के डाइनिंग रूम के एक कोने में एक पुराना स्पीकर था, जिस पर हल्का इंस्ट्रूमेंटल म्यूज़िक बज रहा था: पहले सितार,", "who": "", "voice": "narrator", "diary": false}, {"start": 859.81, "end": 862.6, "text": "फिर संतूर, और फिर, एक ट्रैक के लिए,", "who": "", "voice": "narrator", "diary": false}, {"start": 862.6, "end": 865.47, "text": "बाँसुरी पर एक पुरानी गढ़वाली लोकधुन।", "who": "", "voice": "narrator", "diary": false}, {"start": 865.47, "end": 869.14, "text": "वैसी, जैसी चरवाहे ऊँचे बुग्यालों पर बजाते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 869.14, "end": 871.14, "text": "जैसे ही बाँसुरी शुरू हुई,", "who": "", "voice": "narrator", "diary": false}, {"start": 871.14, "end": 875.44, "text": "उस बड़े आदमी का चम्मच… मुँह तक आधे रास्ते में रुक गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 875.44, "end": 879.51, "text": "और वहीं रुका रहा, टपकता हुआ, गाने के पूरे तीन मिनट।", "who": "", "voice": "narrator", "diary": false}, {"start": 879.51, "end": 881.03, "text": "उसने ऊपर नहीं देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 881.03, "end": 882.07, "text": "वो हिला नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 882.07, "end": 884.86, "text": "जब ट्रैक बदला, उसने चम्मच नीचे रखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 884.86, "end": 888.45, "text": "कटोरा दूर खिसकाया, और फिर उसे हाथ नहीं लगाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 888.9, "end": 892.92, "text": "क्षितिज ने अपनी डायरी में एक लाइन लिखी: बड़े आदमी को बाँसुरी पसंद नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 892.92, "end": 895.19, "text": "फिर उसके आगे एक क्वेश्चन मार्क लगा दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 895.64, "end": 896.51, "text": "और नंदा देवी?", "who": "", "voice": "narrator", "diary": false}, {"start": 896.71, "end": 900.71, "text": "मैंने रोहन से पूछा, क्योंकि मैं सवाल पूछना बंद नहीं कर सकता।", "who": "", "voice": "narrator", "diary": false}, {"start": 900.91, "end": 901.95, "text": "आपने क्लाइंब किया है?", "who": "", "voice": "narrator", "diary": false}, {"start": 902.4, "end": 905.65, "text": "उसकी स्माइल के पीछे कुछ टिमटिमाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 905.65, "end": 910.23, "text": "बस एक सेकंड के लिए, जैसे जलने से पहले ट्यूबलाइट।", "who": "", "voice": "narrator", "diary": false}, {"start": 910.68, "end": 912.96, "text": "नंदा देवी पर अब कोई नहीं चढ़ता, प्रोफ़ेसर।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 913.16, "end": 914.68, "text": "उसने हल्के से कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 914.88, "end": 917.17, "text": "सैंक्चुअरी सालों से बंद है।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 917.17, "end": 919.38, "text": "ऑफ़िशियली, इकोलॉजी के लिए।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 919.58, "end": 922.38, "text": "उसने हाथ बढ़ाकर मेरी नोटबुक उठा ली।", "who": "", "voice": "narrator", "diary": false}, {"start": 922.38, "end": 923.58, "text": "उसने पूछा नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 923.58, "end": 926.38, "text": "उसे हाथों में घुमाया, कवर खोला, सर,", "who": "", "voice": "narrator", "diary": false}, {"start": 926.38, "end": 928.87, "text": "लिखते रहना पढ़ा, और मुस्कुराया।", "who": "", "voice": "narrator", "diary": false}, {"start": 929.07, "end": 929.45, "text": "नाइस।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 929.45, "end": 931.75, "text": "मेरे पास भी बिल्कुल ऐसी ही है।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 932.2, "end": 936.6, "text": "उसने उसे वापस रख दिया, और फिर एक छोटी सी, अजीब चीज़ की।", "who": "", "voice": "narrator", "diary": false}, {"start": 936.6, "end": 942.35, "text": "उसने उसे टेबल के किनारे से एकदम पैरेलल सीधा किया… और फिर एक मिलीमीटर और।", "who": "", "voice": "narrator", "diary": false}, {"start": 942.8, "end": 947.81, "text": "क्षितिज ने एक और लाइन लिखी, और उसके नीचे दो बार लकीर खींची।", "who": "", "voice": "narrator", "diary": false}, {"start": 948.26, "end": 949.38, "text": "रोहन उठ खड़ा हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 949.58, "end": 951.68, "text": "सवॉय एंजॉय कीजिए, आप सब।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 951.68, "end": 955.7, "text": "और भूत जो कुछ कहें, उस सब पर यक़ीन मत कीजिएगा।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 956.15, "end": 959.67, "text": "वो बड़ा आदमी आधा सूप छोड़कर उसके पीछे चला गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 959.67, "end": 965.02, "text": "फ़ायरप्लेस के पास वाले कोने में, गोलू आग की लपटों को फ़िल्म कर रहा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 965.02, "end": 967.54, "text": "या कम से कम उसका फ़ोन उस तरफ़ था।", "who": "", "voice": "narrator", "diary": false}, {"start": 967.54, "end": 970.98, "text": "उसकी छोटी सी लाल लाइट, हमारी टेबल की तरफ़ थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 970.98, "end": 973.12, "text": "मैंने इस बारे में नहीं सोचा।", "who": "", "voice": "narrator", "diary": false}, {"start": 973.12, "end": 974.27, "text": "सोचना चाहिए था।", "who": "", "voice": "narrator", "diary": false}, {"start": 974.72, "end": 977.7, "text": "गब्बर ने दोनों आदमियों को जाते देखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 977.7, "end": 982.0, "text": "और देहरादून के बाद पहली बार, उसने कोई जोक नहीं मारा।", "who": "", "voice": "narrator", "diary": false}, {"start": 982.45, "end": 983.25, "text": "वो आदमी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 983.45, "end": 986.12, "text": "उसने किसी ख़ास से नहीं, बस यूँ ही कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 986.32, "end": 989.43, "text": "पहाड़ की बात ऐसे करता है, जैसे पहाड़ उसका हो।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 990.93, "end": 995.43, "text": "रात के दो बजकर चौदह मिनट पर, मैं तीन वजहों से जाग रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 995.43, "end": 996.69, "text": "बेड बहुत नरम था।", "who": "", "voice": "narrator", "diary": false}, {"start": 996.69, "end": 998.03, "text": "रूम बहुत शांत था।", "who": "", "voice": "narrator", "diary": false}, {"start": 998.03, "end": 1003.01, "text": "और रूम वन-ट्वेल्व के बाहर, कॉरिडोर में कहीं… कोई बात कर रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1003.46, "end": 1005.14, "text": "भूतों वाली बात नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1005.14, "end": 1008.92, "text": "वो धीमा गाना नहीं, जिसका वादा लेजेंड करती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1008.92, "end": 1012.45, "text": "इंसानों वाली बात: धीमी, तेज़, झुँझलाई हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 1012.9, "end": 1015.03, "text": "मैं चाहूँगा कि आपसे कहूँ,", "who": "", "voice": "narrator", "diary": false}, {"start": 1015.03, "end": 1019.03, "text": "कि मैं साइंटिफ़िक क्यूरियोसिटी से देखने गया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1019.03, "end": 1022.78, "text": "मैं गया, क्योंकि मैं ताक-झाँक करने वाला हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1022.78, "end": 1029.59, "text": "मैंने होटल की एक्स्ट्रा शॉल, सफ़ेद, बहुत बड़ी, बहुत गर्म, अपने चारों तरफ़ लपेटी,", "who": "", "voice": "narrator", "diary": false}, {"start": 1029.59, "end": 1034.1, "text": "अपनी नोटबुक उठाई, क्योंकि मैं उसे हर जगह ले जाता हूँ,", "who": "", "voice": "narrator", "diary": false}, {"start": 1034.1, "end": 1035.46, "text": "और दरवाज़ा खोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 1035.91, "end": 1039.85, "text": "कॉरिडोर धुँधले पीले लैंप्स के नीचे दूर तक फैला था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1039.85, "end": 1043.47, "text": "सबसे आख़िर में, पुरानी सर्विस सीढ़ियों के पास,", "who": "", "voice": "narrator", "diary": false}, {"start": 1043.47, "end": 1044.89, "text": "दो शेप्स खड़ी थीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1044.89, "end": 1045.52, "text": "एक पतली।", "who": "", "voice": "narrator", "diary": false}, {"start": 1045.52, "end": 1047.88, "text": "और एक… अलमारी जैसी बनावट वाली।", "who": "", "voice": "narrator", "diary": false}, {"start": 1048.58, "end": 1050.42, "text": "रोहन सहगल… और सूप वाला आदमी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1051.12, "end": 1053.06, "text": "मैं एक पिलर से चिपक गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1053.06, "end": 1058.25, "text": "मैंने लोगों को ऐसा सिर्फ़ फ़िल्मों में करते देखा था, और पता चला,", "who": "", "voice": "narrator", "diary": false}, {"start": 1058.25, "end": 1063.44, "text": "कि ऐसा करके आप बिल्कुल एक पिलर से चिपके हुए आदमी जैसे दिखते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1063.89, "end": 1064.93, "text": "रोहन बोल रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1065.13, "end": 1068.47, "text": "एन-डी पैंसठ का कोर अभी भी वहीं है, भल्ला।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1068.67, "end": 1070.33, "text": "तो अलमारी का एक नाम था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1070.53, "end": 1072.17, "text": "ग्लेशियर पिघल रहा है।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1072.17, "end": 1073.41, "text": "हर साल थोड़ा और।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1073.41, "end": 1077.3, "text": "दो साल में कोई ट्रेकर उसे इंस्टाग्राम पे डाल देगा।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1077.3, "end": 1079.33, "text": "उससे पहले हमें पहुँचना है।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1079.78, "end": 1080.42, "text": "और गीत?", "who": "भल्ला", "voice": "bhalla", "diary": false}, {"start": 1080.62, "end": 1083.27, "text": "उस साइज़ के आदमी के हिसाब से,", "who": "", "voice": "narrator", "diary": false}, {"start": 1083.27, "end": 1086.74, "text": "भल्ला की आवाज़ हैरानी की हद तक नरम थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1086.94, "end": 1088.64, "text": "आख़िरी हिस्सा तो मिला ही नहीं, सर।", "who": "भल्ला", "voice": "bhalla", "diary": false}, {"start": 1089.09, "end": 1090.96, "text": "मलेथा वाला बुड्ढा जानता है।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1090.96, "end": 1091.79, "text": "वो बता देगा।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1091.99, "end": 1092.79, "text": "एक पॉज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 1092.99, "end": 1095.33, "text": "सब बता देते हैं, भल्ला।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1095.33, "end": 1098.07, "text": "बस… सही तरह पूछना पड़ता है।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1098.52, "end": 1100.4, "text": "उसके हाथ में एक नोटबुक थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1100.4, "end": 1101.26, "text": "ब्राउन लेदर।", "who": "", "voice": "narrator", "diary": false}, {"start": 1101.26, "end": 1102.35, "text": "थोड़ी घिसी हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 1103.05, "end": 1104.25, "text": "बिल्कुल… मेरी जैसी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1104.95, "end": 1105.86, "text": "एन-डी पैंसठ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1105.86, "end": 1106.16, "text": "कोर।", "who": "", "voice": "narrator", "diary": false}, {"start": 1106.16, "end": 1106.84, "text": "ग्लेशियर।", "who": "", "voice": "narrator", "diary": false}, {"start": 1106.84, "end": 1114.35, "text": "मैं कंप्यूटर्स पढ़ाता हूँ, फ़िज़िक्स नहीं, लेकिन रात के एक बजे मैंने इतनी डॉक्यूमेंट्रीज़ देखी हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 1114.35, "end": 1117.99, "text": "कि मुझे लगा, मेरा पेट कार्पेट के आर-पार धँस गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1118.44, "end": 1120.59, "text": "मैंने सावधानी से… एक क़दम पीछे लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1121.04, "end": 1123.66, "text": "सीधे… एक रूम-सर्विस ट्रॉली में!", "who": "", "voice": "narrator", "diary": false}, {"start": 1124.11, "end": 1128.14, "text": "पता चला, वो ट्रॉली मसूरी का हर एक चम्मच ढो रही थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1128.14, "end": 1129.9, "text": "वो मार्बल पर ऐसे गिरे,", "who": "", "voice": "narrator", "diary": false}, {"start": 1129.9, "end": 1133.52, "text": "जैसे कोई ब्रास बैंड सीढ़ियों से लुढ़क रहा हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 1134.22, "end": 1135.34, "text": "दोनों आदमी… मुड़े।", "who": "", "voice": "narrator", "diary": false}, {"start": 1136.04, "end": 1144.68, "text": "उस मोमेंट पर रोहन और भल्ला ने जो देखा, और ये मुझे पता है, क्योंकि बाद में मैंने वो फ़ुटेज देखी है, वो था एक लंबा,", "who": "", "voice": "narrator", "diary": false}, {"start": 1144.68, "end": 1149.66, "text": "सफ़ेद आकार, सिर से पैर तक लिपटा हुआ, रात के दो बजकर चौदह मिनट पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 1149.66, "end": 1153.95, "text": "एक हॉन्टेड कॉरिडोर के आख़िर में, बिल्कुल स्थिर खड़ा हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1154.4, "end": 1156.15, "text": "भल्ला एक क़दम पीछे हटा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1156.15, "end": 1157.75, "text": "उसका हाथ सीने पर गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1158.2, "end": 1159.48, "text": "रोहन ज़रा भी नहीं हिला।", "who": "", "voice": "narrator", "diary": false}, {"start": 1159.68, "end": 1160.16, "text": "भल्ला।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1160.36, "end": 1161.8, "text": "उसने बहुत शांति से कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1162.0, "end": 1162.9, "text": "भूत नहीं है… पकड़ो!", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1163.6, "end": 1164.36, "text": "मैं भागा!", "who": "", "voice": "narrator", "diary": false}, {"start": 1165.06, "end": 1167.64, "text": "मैं वैसे भागा, जैसे वो आदमी भागता है,", "who": "", "voice": "narrator", "diary": false}, {"start": 1167.64, "end": 1172.44, "text": "जिसने बारह साल स्टूडेंट्स को समझाया हो कि फ़िज़िकल फ़िटनेस ज़रूरी है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1172.44, "end": 1176.48, "text": "कॉरिडोर के आधे रास्ते में, मैं शॉल में उलझकर ज़ोर से गिरा,", "who": "", "voice": "narrator", "diary": false}, {"start": 1176.48, "end": 1180.24, "text": "और मेरी नोटबुक हाथ से छूटकर, कार्पेट पर फिसलती चली गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 1180.24, "end": 1181.84, "text": "भल्ला ठीक मेरे पीछे था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1181.84, "end": 1188.1, "text": "वो भी उन्हीं चम्मचों पर पड़ा, फिसला, कंधे के बल दीवार से टकराया, और उसके हाथ की नोटबुक भी,", "who": "", "voice": "narrator", "diary": false}, {"start": 1188.1, "end": 1192.9, "text": "जो रोहन ने अपने हाथ ख़ाली करने के लिए उसे पकड़ा दी थी… फिसलती चली गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 1193.35, "end": 1195.89, "text": "ब्राउन लेदर की दो नोटबुक्स।", "who": "", "voice": "narrator", "diary": false}, {"start": 1195.89, "end": 1197.58, "text": "एक धुँधला कॉरिडोर।", "who": "", "voice": "narrator", "diary": false}, {"start": 1197.58, "end": 1199.56, "text": "एक डरा हुआ प्रोफ़ेसर।", "who": "", "voice": "narrator", "diary": false}, {"start": 1200.01, "end": 1203.37, "text": "मैंने जो सबसे पास थी, उठाई, और भागता रहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1203.82, "end": 1205.96, "text": "मोड़ पर, मेरे चेहरे के सामने,", "who": "", "voice": "narrator", "diary": false}, {"start": 1205.96, "end": 1208.78, "text": "एक चौंधियाने वाली सफ़ेद रोशनी फट पड़ी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1209.23, "end": 1210.61, "text": "घोस्ट फ़ैमिली।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 1210.81, "end": 1214.83, "text": "उसके पीछे से एक आवाज़ फुसफुसाई, ख़ुशी से काँपती हुई,", "who": "", "voice": "narrator", "diary": false}, {"start": 1215.03, "end": 1216.65, "text": "वो देखो… सफ़ेद साया…", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 1217.1, "end": 1217.52, "text": "गोलू।", "who": "", "voice": "narrator", "diary": false}, {"start": 1217.52, "end": 1219.49, "text": "रिंग लाइट फ़ुल पावर पर।", "who": "", "voice": "narrator", "diary": false}, {"start": 1219.49, "end": 1221.29, "text": "और वो मुझ पर नहीं थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1221.29, "end": 1226.35, "text": "वो सीधी मेरे पीछे से निकलकर… भल्ला की आँखों में पड़ रही थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1226.8, "end": 1231.61, "text": "बाद में मैं सोचता रहा, कि गोलू उस मोड़ पर कैसे खड़ा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 1231.61, "end": 1234.59, "text": "पूरे कपड़ों में, कैमरा पहले से ऑन,", "who": "", "voice": "narrator", "diary": false}, {"start": 1234.59, "end": 1237.57, "text": "जबकि अभी एक भी चम्मच नहीं गिरा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1237.57, "end": 1240.98, "text": "उस वक़्त, मैं ज़िंदा रहने में बिज़ी था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1241.43, "end": 1246.04, "text": "भल्ला, चौंधियाया हुआ, एक दरवाज़े की चौखट से जा टकराया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1246.04, "end": 1246.98, "text": "गोलू चीख़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1246.98, "end": 1248.0, "text": "भल्ला चीख़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1248.0, "end": 1253.04, "text": "मैं ये जानने के लिए नहीं रुका कि कौन ज़्यादा ज़ोर से चीख़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1253.04, "end": 1256.2, "text": "मैं रूम वन-ट्वेल्व पहुँचा, अंदर घुसा,", "who": "", "voice": "narrator", "diary": false}, {"start": 1256.2, "end": 1260.47, "text": "दरवाज़ा लॉक किया, और उससे टिककर फ़र्श पर फिसल गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1260.92, "end": 1264.65, "text": "एक लॉक्ड दरवाज़ा… सवॉय… आधी रात।", "who": "", "voice": "narrator", "diary": false}, {"start": 1265.1, "end": 1268.37, "text": "मैं हँसने लगा… और फिर, बहुत जल्दी रुक गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1269.87, "end": 1271.05, "text": "तुमने सपना देखा।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 1271.25, "end": 1273.54, "text": "शाओनी ने ब्रेकफ़ास्ट पर मुझसे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1273.54, "end": 1276.77, "text": "वो सर्जिकल प्रिसीज़न से टोस्ट पर बटर लगा रही थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1276.97, "end": 1278.12, "text": "हेवी डिनर।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 1278.12, "end": 1279.51, "text": "अनजाना होटल।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 1279.51, "end": 1280.43, "text": "क्लासिक।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 1280.88, "end": 1282.41, "text": "मैं प्रोफ़ेसर हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1282.61, "end": 1283.4, "text": "मैंने उससे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1283.6, "end": 1285.27, "text": "मैं सपने में चम्मच नहीं गिराता।", "who": "", "voice": "narrator", "diary": false}, {"start": 1285.72, "end": 1287.33, "text": "क्षितिज कुछ नहीं बोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 1287.33, "end": 1289.17, "text": "उसने बस अपना फ़ोन घुमाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 1289.17, "end": 1292.03, "text": "और टेबल पर अपनी बहन की तरफ़ खिसका दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1292.48, "end": 1296.6, "text": "गोलू की वीडियो पर पहले ही बारह लाख व्यूज़ थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 1296.6, "end": 1300.89, "text": "टाइटल था: रियल घोस्ट कॉट एट सवॉय, नॉट क्लिकबेट!", "who": "", "voice": "narrator", "diary": false}, {"start": 1300.89, "end": 1304.64, "text": "और थंबनेल में एक लंबा, सफ़ेद धुँधला आकार।", "who": "", "voice": "narrator", "diary": false}, {"start": 1304.64, "end": 1305.0, "text": "मैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1305.0, "end": 1309.48, "text": "डिस्क्रिप्शन में, स्पिरिट्स आइडेंटिफ़ाइड के नीचे,", "who": "", "voice": "narrator", "diary": false}, {"start": 1309.48, "end": 1313.04, "text": "मुझे लिखा गया था: अननोन एंटिटी… फ़ीमेल?", "who": "", "voice": "narrator", "diary": false}, {"start": 1313.49, "end": 1315.57, "text": "शाओनी ने उसे दो बार देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1315.57, "end": 1317.57, "text": "उसने टोस्ट नीचे रख दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1318.02, "end": 1318.56, "text": "भाई।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 1318.76, "end": 1321.06, "text": "क्षितिज ने कमेंट्स स्क्रॉल करते हुए मुझसे कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 1321.26, "end": 1323.53, "text": "आपका कमेंट सेक्शन आपसे ज़्यादा फ़ेमस है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 1323.98, "end": 1325.88, "text": "मैंने उसे तीसरी बार देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1325.88, "end": 1329.08, "text": "भूत, यानी मैं, स्क्रीन पर ग्यारह सेकंड था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1329.08, "end": 1333.03, "text": "और कॉरिडोर के आख़िर में खड़ा वो आदमी, आधा मुड़ा हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 1333.03, "end": 1337.44, "text": "रिंग लाइट से सफ़ेद पड़ा चेहरा… स्क्रीन पर उन्नीस सेकंड था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1337.44, "end": 1339.41, "text": "एक भूत वाली वीडियो के लिए,", "who": "", "voice": "narrator", "diary": false}, {"start": 1339.41, "end": 1342.53, "text": "उसे ज़िंदा लोगों में अजीब सी दिलचस्पी थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1342.98, "end": 1345.05, "text": "मैंने इसे ख़राब एडिटिंग मान लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1345.5, "end": 1350.1, "text": "डाइनिंग रूम के उस पार, गोलू अकेले बैठा आलू पराठा खा रहा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 1350.1, "end": 1352.83, "text": "और वो अपने फ़ोन को नहीं देख रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1352.83, "end": 1356.26, "text": "वो रोहन सहगल की टेबल को देख रहा था, वैसे ही,", "who": "", "voice": "narrator", "diary": false}, {"start": 1356.26, "end": 1361.26, "text": "जैसे आप किसी दरवाज़े को देखते हैं जिसके खुलने की आपको उम्मीद हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 1361.71, "end": 1363.78, "text": "रोहन की टेबल ख़ाली थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1363.78, "end": 1365.58, "text": "नए सिरे से सजी हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 1365.58, "end": 1366.14, "text": "अनछुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 1366.84, "end": 1367.96, "text": "मैंने वेटर से पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1368.66, "end": 1369.44, "text": "मिस्टर सहगल?", "who": "वेटर", "voice": "waiter", "diary": false}, {"start": 1369.64, "end": 1370.28, "text": "उसने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1370.48, "end": 1371.78, "text": "चेक आउट कर गए, सर।", "who": "वेटर", "voice": "waiter", "diary": false}, {"start": 1371.78, "end": 1372.78, "text": "सुबह पाँच बजे।", "who": "वेटर", "voice": "waiter", "diary": false}, {"start": 1374.28, "end": 1376.04, "text": "हम अपने बैग्स लेने ऊपर गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 1376.74, "end": 1378.74, "text": "रूम वन-ट्वेल्व की… तलाशी ली गई थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1379.19, "end": 1381.16, "text": "तहस-नहस नहीं किया गया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1381.16, "end": 1383.14, "text": "तलाशी ली गई थी, ध्यान से।", "who": "", "voice": "narrator", "diary": false}, {"start": 1383.14, "end": 1387.33, "text": "ड्रॉअर्स खोलकर फिर बंद किए गए थे, कुछ मिलीमीटर टेढ़े।", "who": "", "voice": "narrator", "diary": false}, {"start": 1387.33, "end": 1391.2, "text": "मेरा सूटकेस अनज़िप करके, फिर ज़िप कर दिया गया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1391.2, "end": 1395.32, "text": "गद्दा अपने बेस पर ज़रा सा तिरछा था, जैसे तब होता है,", "who": "", "voice": "narrator", "diary": false}, {"start": 1395.32, "end": 1398.32, "text": "जब कोई उसे उठाकर जल्दी में वापस रख दे।", "who": "", "voice": "narrator", "diary": false}, {"start": 1398.32, "end": 1403.62, "text": "जिसने भी ये किया था, वो चाहता था कि मुझे पता चले… और ये भी पता चले,", "who": "", "voice": "narrator", "diary": false}, {"start": 1403.62, "end": 1405.83, "text": "कि उसने ये तमीज़ से किया है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1406.28, "end": 1409.17, "text": "शाओनी देर तक दरवाज़े पर खड़ी रही।", "who": "", "voice": "narrator", "diary": false}, {"start": 1409.17, "end": 1411.45, "text": "अब वो सपना नहीं कह रही थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1411.9, "end": 1412.52, "text": "पार्थ।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 1412.72, "end": 1413.98, "text": "उसने धीरे से कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1414.18, "end": 1416.07, "text": "चोर होता, तो वॉलेट ले जाता।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 1416.07, "end": 1418.17, "text": "ये कुछ स्पेसिफ़िक ढूँढ रहा था।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 1418.37, "end": 1420.61, "text": "उसने दरवाज़े पर लिखे रूम नंबर को देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1420.81, "end": 1423.29, "text": "और उसको पता था, तुम कौन से कमरे में हो।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 1423.74, "end": 1429.1, "text": "लॉजिक, ठंडा और तेज़, जैसे मसूरी के नल के पानी की बाल्टी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1429.55, "end": 1431.15, "text": "फिर उसने कुछ ऐसा किया,", "who": "", "voice": "narrator", "diary": false}, {"start": 1431.15, "end": 1434.44, "text": "जो मुझे नहीं लगता उसे पता था कि वो कर रही है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1434.44, "end": 1436.71, "text": "वो बहुत कैज़ुअली एक तरफ़ खिसकी,", "who": "", "voice": "narrator", "diary": false}, {"start": 1436.71, "end": 1440.51, "text": "जब तक कि वो क्षितिज और कॉरिडोर के बीच में नहीं आ गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 1440.51, "end": 1442.12, "text": "क्षितिज ने नोटिस किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1442.12, "end": 1443.37, "text": "वो हमेशा करता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1443.37, "end": 1449.21, "text": "उसने कुछ कहा नहीं; बस थोड़ा और सीधा खड़ा हो गया, जैसे छोटे भाई तब खड़े होते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 1449.21, "end": 1453.53, "text": "जब उनकी हिफ़ाज़त की जा रही हो, और वो चाहते हों कि न की जाए।", "who": "", "voice": "narrator", "diary": false}, {"start": 1453.98, "end": 1456.08, "text": "मैंने अपना बैग चेक किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1456.08, "end": 1456.61, "text": "वॉलेट।", "who": "", "voice": "narrator", "diary": false}, {"start": 1456.61, "end": 1457.04, "text": "फ़ोन।", "who": "", "voice": "narrator", "diary": false}, {"start": 1457.04, "end": 1457.66, "text": "चार्जर।", "who": "", "voice": "narrator", "diary": false}, {"start": 1457.66, "end": 1458.62, "text": "तीन स्वेटर।", "who": "", "voice": "narrator", "diary": false}, {"start": 1459.07, "end": 1460.66, "text": "नोटबुक नहीं थी… मेरी वाली नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1461.11, "end": 1468.04, "text": "कमरे में अकेली नोटबुक वो थी, जो मैंने दो बजकर चौदह मिनट पर कॉरिडोर के फ़र्श से उठाई थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 1468.04, "end": 1470.18, "text": "और तकिए के नीचे ठूँस दी थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1470.18, "end": 1471.14, "text": "ब्राउन लेदर।", "who": "", "voice": "narrator", "diary": false}, {"start": 1471.14, "end": 1472.33, "text": "थोड़ी घिसी हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 1473.03, "end": 1473.98, "text": "मैंने उसे… खोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 1474.68, "end": 1476.89, "text": "कवर के अंदर, कोई सर, लिखते रहना नहीं था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1477.34, "end": 1481.15, "text": "पहले पेज में एक ब्लैक-एंड-व्हाइट फ़ोटो दबी थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 1481.15, "end": 1484.38, "text": "कोने घिसकर नरम हो चुके थे: एक ग्लेशियर,", "who": "", "voice": "narrator", "diary": false}, {"start": 1484.38, "end": 1487.77, "text": "एक पहाड़ी रिज, बर्फ़ पर एक काला सा धब्बा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1487.77, "end": 1492.82, "text": "पीछे, फीकी पड़ती नीली स्याही में: स्प्रिंग, उन्नीस सौ छियासठ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1492.82, "end": 1495.38, "text": "धब्बे के ऊपर, साँस जितनी हल्की,", "who": "", "voice": "narrator", "diary": false}, {"start": 1495.38, "end": 1498.28, "text": "बर्फ़ से उठती किसी चीज़ की एक लकीर।", "who": "", "voice": "narrator", "diary": false}, {"start": 1498.98, "end": 1499.61, "text": "भाप।", "who": "", "voice": "narrator", "diary": false}, {"start": 1500.31, "end": 1504.84, "text": "अगले पेजेज़ पर कोऑर्डिनेट्स थे, काटकर दोबारा लिखे हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 1504.84, "end": 1506.52, "text": "एक्सपीडिशन की डेट्स।", "who": "", "voice": "narrator", "diary": false}, {"start": 1506.52, "end": 1507.28, "text": "ऊँचाइयाँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1507.28, "end": 1511.23, "text": "गाँवों के नामों की एक लिस्ट, मलेथा, द्रोणागिरी,", "who": "", "voice": "narrator", "diary": false}, {"start": 1511.23, "end": 1514.75, "text": "मुनस्यारी, कुछ पर टिक, कुछ पर दो बार गोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 1515.2, "end": 1519.08, "text": "और फिर, बहुत ध्यान से लिखा हुआ, एक गीत।", "who": "", "voice": "narrator", "diary": false}, {"start": 1519.53, "end": 1521.82, "text": "जहाँ पानी के बदले बेटा दिया…", "who": "", "voice": "narrator", "diary": false}, {"start": 1522.27, "end": 1524.57, "text": "वहाँ से पहला पाठ लिया।…", "who": "", "voice": "narrator", "diary": false}, {"start": 1525.02, "end": 1527.58, "text": "जहाँ पत्थर ने नदी रोकी…", "who": "", "voice": "narrator", "diary": false}, {"start": 1528.03, "end": 1530.24, "text": "वहाँ नंदा की आँख खुली…", "who": "", "voice": "narrator", "diary": false}, {"start": 1530.69, "end": 1532.98, "text": "नंदा की गरम शिला, बर्फ़ में सोई…", "who": "", "voice": "narrator", "diary": false}, {"start": 1533.43, "end": 1537.55, "text": "जिसने छुई, वो लौट के ना रोई…", "who": "", "voice": "narrator", "diary": false}, {"start": 1538.0, "end": 1540.46, "text": "आख़िरी छंद फाड़ लिया गया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1540.46, "end": 1543.2, "text": "फटा हुआ किनारा साफ़ दिख रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1543.65, "end": 1553.29, "text": "मैंने वही किया, जो कोई भी टेक-सैवी प्रोफ़ेसर करता है, जब उसके हाथ में कोई ख़तरनाक सीक्रेट आ जाए: मैंने हर पेज की फ़ोटो खींची,", "who": "", "voice": "narrator", "diary": false}, {"start": 1553.29, "end": 1556.54, "text": "सब एक एन्क्रिप्टेड फ़ोल्डर में अपलोड किया,", "who": "", "voice": "narrator", "diary": false}, {"start": 1556.54, "end": 1560.16, "text": "और उसका नाम रखा, यूनिट फ़ोर प्रैक्टिकल मार्क्स।", "who": "", "voice": "narrator", "diary": false}, {"start": 1560.16, "end": 1562.71, "text": "क्योंकि इतिहास में आज तक किसी ने,", "who": "", "voice": "narrator", "diary": false}, {"start": 1562.71, "end": 1565.57, "text": "अपनी मर्ज़ी से, वो फ़ोल्डर नहीं खोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 1566.02, "end": 1566.63, "text": "पार्थ।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 1566.83, "end": 1568.83, "text": "शाओनी की आवाज़ बदल गई थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1569.03, "end": 1569.82, "text": "गब्बर भैया।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 1570.27, "end": 1573.17, "text": "गब्बर गाड़ी की चाबियाँ लिए दरवाज़े पर खड़ा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1573.17, "end": 1574.93, "text": "वो हमें जल्दी करवाने आया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1574.93, "end": 1577.26, "text": "अब वो किसी को जल्दी नहीं करवा रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1577.26, "end": 1580.16, "text": "वो मेरे कंधे के ऊपर से खुले पेज को देख रहा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 1580.16, "end": 1582.55, "text": "और उसके चेहरे का सारा रंग उड़ चुका था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1583.0, "end": 1584.07, "text": "ये गीत।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 1584.27, "end": 1585.48, "text": "उसने धीरे से कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1585.48, "end": 1587.19, "text": "वो मुझसे नहीं कह रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1587.19, "end": 1588.61, "text": "वो गीत से कह रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1588.81, "end": 1590.17, "text": "ये… मेरी नानी गाती थी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 1590.87, "end": 1592.21, "text": "किसी ने कुछ नहीं कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1592.91, "end": 1598.34, "text": "फिर, क्योंकि मैं प्रोफ़ेसर हूँ और हमेशा आख़िरी पेज पहले देखता हूँ,", "who": "", "voice": "narrator", "diary": false}, {"start": 1598.34, "end": 1601.05, "text": "और न जाने कैसे इस बार भूल गया था,", "who": "", "voice": "narrator", "diary": false}, {"start": 1601.05, "end": 1603.69, "text": "मैंने नोटबुक का आख़िरी पेज पलटा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1604.14, "end": 1605.54, "text": "स्याही ताज़ा थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1605.54, "end": 1607.57, "text": "अभी भी हल्की चमकती हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 1607.57, "end": 1612.86, "text": "उसी सुबह लिखी हुई, उसी सधी हुई लिखावट में, जिसमें वो गीत था:", "who": "", "voice": "narrator", "diary": false}, {"start": 1613.31, "end": 1614.87, "text": "प्रोफ़ेसर पार्थ।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1614.87, "end": 1616.33, "text": "रूम वन-ट्वेल्व।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1616.78, "end": 1617.96, "text": "आप मेरी नोटबुक रखिए।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1617.96, "end": 1619.2, "text": "मैं आपकी रख लेता हूँ।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1619.9, "end": 1621.31, "text": "फिर मिलेंगे।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1621.31, "end": 1621.66, "text": "आर।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1622.36, "end": 1625.7, "text": "क्षितिज ने उसे मेरे कंधे के ऊपर से पढ़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1625.7, "end": 1628.13, "text": "शाओनी ने उसके कंधे के ऊपर से।", "who": "", "voice": "narrator", "diary": false}, {"start": 1628.13, "end": 1632.72, "text": "गब्बर खिड़की तक गया, और नीचे सवॉय की पार्किंग में देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1633.17, "end": 1634.04, "text": "प्रोफ़ेसर साहब।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 1634.24, "end": 1635.42, "text": "उसने बिना मुड़े कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1635.87, "end": 1636.27, "text": "नीचे,", "who": "", "voice": "narrator", "diary": false}, {"start": 1636.27, "end": 1641.02, "text": "काले शीशों वाली एक काली एस-यू-वी का इंजन स्टार्ट हो चुका था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1641.02, "end": 1642.05, "text": "वो हिली नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1642.05, "end": 1645.93, "text": "बस वहीं खड़ी रही, चलती हुई, गेट की तरफ़ मुँह किए।", "who": "", "voice": "narrator", "diary": false}, {"start": 1646.38, "end": 1648.7, "text": "वो तब तक नहीं गई… जब तक हम नहीं गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 1649.15, "end": 1651.19, "text": "क्षितिज की डायरी से।", "who": "", "voice": "narrator", "diary": true}, {"start": 1651.19, "end": 1652.51, "text": "डे वन, मसूरी।", "who": "", "voice": "narrator", "diary": true}, {"start": 1652.96, "end": 1656.02, "text": "डिनर पर आर. ने पार्थ भाई की नोटबुक उठाई,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1656.02, "end": 1658.47, "text": "और कवर का अंदर वाला हिस्सा खोला।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1658.47, "end": 1660.38, "text": "वो तारीफ़ नहीं कर रहा था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1660.38, "end": 1664.67, "text": "वो चेक कर रहा था कि वो उसकी वाली से मैच करती है या नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1664.67, "end": 1667.81, "text": "फिर उसने उसे टेबल के किनारे से सीधा किया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1667.81, "end": 1669.03, "text": "ऐसा कौन करता है?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1669.48, "end": 1671.84, "text": "भल्ला के जूतों पर ग्रे गाद लगी थी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1671.84, "end": 1672.94, "text": "ग्लेशियर की गाद।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1672.94, "end": 1675.09, "text": "मसूरी में कोई ग्लेशियर नहीं है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1675.09, "end": 1677.3, "text": "जब गोलू की रिंग लाइट उस पर पड़ी,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1677.3, "end": 1679.52, "text": "तो उसने बस आँखें नहीं मिचमिचाईं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1679.52, "end": 1682.84, "text": "वो काँप गया, जैसे उसने कोई असली भूत देख लिया हो।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1683.29, "end": 1687.63, "text": "जब बाँसुरी पर चरवाहों वाली धुन बजी, भल्ला ने खाना बंद कर दिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1687.63, "end": 1689.81, "text": "बड़े आदमी को बाँसुरी पसंद नहीं?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1689.81, "end": 1692.26, "text": "बड़े आदमी को… वो बाँसुरी पसंद नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1692.71, "end": 1696.24, "text": "चम्मच गिरने से पहले ही गोलू फ़िल्म कर रहा था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1696.24, "end": 1697.81, "text": "वो जाग क्यों रहा था?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1697.81, "end": 1699.15, "text": "वो वहाँ क्यों था?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1699.6, "end": 1702.16, "text": "गोलू: टोपी के सिवा सब कुछ नया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1702.16, "end": 1706.26, "text": "पुरानी टोपी, पुराना बैज, कहीं ऊँचाई पर हो आई है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1706.26, "end": 1708.4, "text": "एक पुरानी चीज़ क्यों रखी?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1708.85, "end": 1711.41, "text": "गब्बर भैया की नानी को गीत पता था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1711.41, "end": 1712.72, "text": "और किसकी नानी को?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1713.17, "end": 1715.43, "text": "दीदी कहती हैं, नो ड्रामा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1715.43, "end": 1716.79, "text": "देखो, डे ज़ीरो।", "who": "क्षितिज", "voice": "kshitij", "diary": true}], "scenes": [{"at": 20.19, "bed": "airport"}, {"at": 209.9, "bed": "outdoor"}, {"at": 342.23, "bed": "drive"}, {"at": 433.87, "bed": "lobby"}, {"at": 615.96, "bed": "dining"}, {"at": 655.39, "bed": "mystery"}, {"at": 989.73, "bed": "night"}, {"at": 1062.69, "bed": "tension"}, {"at": 1268.67, "bed": "breakfast"}, {"at": 1373.08, "bed": "suspense"}, {"at": 1647.95, "bed": "diary"}, {"at": 1647.95, "bed": "diary"}], "hits": [{"at": 21.24, "fx": "chime"}, {"at": 258.29, "fx": "bonnet"}, {"at": 295.06, "fx": "boot"}, {"at": 343.28, "fx": "carstart"}, {"at": 397.45, "fx": "horn"}, {"at": 434.92, "fx": "cardoor"}, {"at": 460.03, "fx": "golu"}, {"at": 569.44, "fx": "phonering"}, {"at": 593.37, "fx": "cooker"}, {"at": 612.95, "fx": "sting_light"}, {"at": 755.15, "fx": "sting"}, {"at": 850.56, "fx": "flute"}, {"at": 1012.75, "fx": "creak"}, {"at": 1035.76, "fx": "steps_slow"}, {"at": 1120.89, "fx": "crash"}, {"at": 1134.07, "fx": "sting"}, {"at": 1163.45, "fx": "run"}, {"at": 1203.67, "fx": "flash"}, {"at": 1241.28, "fx": "thud"}, {"at": 1260.77, "fx": "door"}, {"at": 1376.59, "fx": "sting"}, {"at": 1453.83, "fx": "zip"}, {"at": 1472.88, "fx": "page"}, {"at": 1498.83, "fx": "sting"}, {"at": 1519.38, "fx": "flute"}, {"at": 1570.12, "fx": "keys"}, {"at": 1603.99, "fx": "sting"}, {"at": 1635.72, "fx": "suv"}], "next": {"label": "एपिसोड 2", "en": "Rule One: Never Look Back at the Ghat", "hook": "पीछे एक काली एस-यू-वी। आगे एक घाट। और पहाड़ का पहला नियम: पीछे मुड़कर मत देखना।"}};
